// gen-vm-content.mjs — PLAN-047 T2/T3: regenerate the VM seed adapter from
// the single-source demo document. content.ts is the ONLY place the document
// lives; this script mechanically derives src/front/utils/app_ext.vm.at from
// it (escaped single-line Auto string literal), so both render tracks start
// from the same text and cannot drift.
//
// Usage (from autodown/demo/auto):  node scripts/gen-vm-content.mjs
// Generated file carries its own DO-NOT-EDIT header pointing back here.
// Escape convention per the .at precedents (a2r.at etc.): \n inside the
// double-quoted literal, backslash and quote escaped.

import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const here = dirname(fileURLToPath(import.meta.url))
const contentPath = join(here, '..', '..', 'src', 'content.ts')
const outPath = join(here, '..', 'src', 'front', 'utils', 'app_ext.vm.at')

const ts = readFileSync(contentPath, 'utf8')

// The template literal: first backtick after `return` opens, the LAST
// backtick in the file closes (inner backticks are \`-escaped in the TS
// source, so they never terminate the literal).
const open = ts.indexOf('`', ts.indexOf('return'))
const close = ts.lastIndexOf('`')
if (open < 0 || close <= open) {
  console.error(`gen-vm-content: no template literal found in ${contentPath}`)
  process.exit(1)
}
// Undo the TS template-literal escapes to get the real document text.
const doc = ts
  .slice(open + 1, close)
  .replace(/\\`/g, '`')
  .replace(/\\\$\{/g, '${')
  .replace(/\\\\/g, '\\')

if (!doc.startsWith('# Heading One')) {
  console.error('gen-vm-content: document does not start with "# Heading One" — content.ts layout changed?')
  process.exit(1)
}
if (doc.includes('\r')) {
  console.error('gen-vm-content: CRLF in content.ts would drift the seed — normalize the file to LF')
  process.exit(1)
}

// Escape for a single-line Auto double-quoted literal.
const escaped = doc
  .replace(/\\/g, '\\\\')
  .replace(/"/g, '\\"')
  .replace(/\n/g, '\\n')
  .replace(/\t/g, '\\t')

const out = `// app_ext.vm.at — GENERATED by scripts/gen-vm-content.mjs — DO NOT EDIT.
// Generated-from: ../../src/content.ts (the demo document — single source for
// both render tracks); regenerate from autodown/demo/auto with:
//   node scripts/gen-vm-content.mjs
// PLAN-047 T2: this pure-Auto adapter fn is a real VM module symbol (Plan 442
// A3 ext adapter chain), consumed through the top-level \`use.web.fn\` in
// src/front/app.at so the VM starts with the same document as the vue track.
// The remaining ext symbols (is_vue/logSave/logCancel/useDemoAppBridge) are
// NOT declared here — they keep their platform-stub semantics. The vue build
// never loads this file (auto-man copies widget-use ext sources only; the SFC
// keeps importing the real app_ext.ts).
fn initial_content() str { return "${escaped}" }
`

writeFileSync(outPath, out)
console.log(`gen-vm-content: wrote ${outPath} (${doc.length} chars of document, ${escaped.length} escaped)`)
